dur = {'A':3,'B':4,'C':2,'D':5,'E':3,'F':2}
pred = {'A':[],'B':['A'],'C':['A'],'D':['B'],'E':['C'],'F':['D','E']}
order = ['A','B','C','D','E','F']
ES, EF = {}, {}
for t in order:
    ES[t] = max([EF[p] for p in pred[t]], default=0)
    EF[t] = ES[t] + dur[t]
T = max(EF.values())
succ = {t: [s for s in order if t in pred[s]] for t in order}
LF, LS = {}, {}
for t in reversed(order):
    LF[t] = min([LS[s] for s in succ[t]], default=T)
    LS[t] = LF[t] - dur[t]
print(T)
print(LS['C'] - ES['C'])
print(LS['E'] - ES['E'])
